<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ucfirst($status)}} Students - Quick</title><style>body{font-family:Arial;background:#f5f7fb;color:#1f2937;margin:0}.wrap{max-width:1400px;margin:auto;padding:20px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;margin-top:15px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:8px;border-bottom:1px solid #eee;text-align:left}th{background:#2563eb;color:#fff}input{padding:8px;border:1px solid #d0d5dd;border-radius:7px}.btn{padding:7px 10px;border-radius:7px;background:#111827;color:#fff;text-decoration:none;border:0}.muted{color:#667085}.copy{cursor:pointer;text-decoration:underline}.actions{white-space:nowrap}.pager{margin-top:15px}</style></head><body><div class="wrap"><h1>{{ucfirst($status)}} Student List (Quick)</h1><a class="btn" href="{{route('admin.dashboard')}}">Dashboard</a><div class="card"><form method="GET"><input name="search" value="{{request('search')}}" placeholder="ID, name, phone, WhatsApp"> <button class="btn">Search</button></form><div style="overflow:auto"><table><thead><tr><th>No</th><th>Name</th><th>WhatsApp</th><th>Telegram</th><th>Created</th><th>Point</th><th>Join Point</th><th>Counsellor/Trainer</th><th>Activated</th><th>Action</th></tr></thead><tbody>@forelse($students as $s)<tr><td class="copy" onclick="navigator.clipboard&&navigator.clipboard.writeText('{{addslashes($s->student_no)}}')">{{$s->student_no}}</td><td>{{$s->student_name}}</td><td>{{$s->student_whatsapp ?: $s->student_phone}}</td><td>{{$s->student_telegram}}</td><td>{{$s->created_at}}</td><td>{{$s->student_point}}</td><td>{{$s->joining_point}}</td><td>{{trim($s->counsellor_name) ?: '-'}}</td><td>{{$s->activated_at ?: '-'}}</td><td class="actions"><a class="btn" href="{{route('admin.students.edit',$s->id)}}">Edit</a>@if($status==='active') <a class="btn" href="{{route('admin.finance.passbook',['student_no'=>$s->student_no])}}">Passbook</a>@endif</td></tr>@empty<tr><td colspan="10">No students found.</td></tr>@endforelse</tbody></table></div><div class="pager">{{$students->links()}}</div></div></div></body></html>